using System;using System.Collections.Generic;using System.Data;using System.Drawing;using System.IO;using System.Linq;using System.Net;using System.Text;using System.Threading.Tasks;using System.Windows.Forms;
namespace XzyBattleStats {
sealed class RankSeason {public int Code;public string Name;public long StartTime,EndTime;}
sealed class RankPlayer {public string Id,Name,Dan;public int Order;public long Score;}
sealed class RankBoard {public int AreaId,Mode,SeasonCode;public string SeasonName;public long FetchedAt;public List<RankPlayer> Players=new List<RankPlayer>();public string Key{get{return AreaId+":"+Mode+":"+SeasonCode;}}}
sealed class RankCache {public string Format="XZY-LadderCache-PC";public int Version=1;public List<RankSeason> Seasons=new List<RankSeason>();public List<RankBoard> Boards=new List<RankBoard>();}
sealed class RankEncounter {public RankPlayer Player;public int Games,Wins,Named;public string Rate{get{return Games==0?"—":(100.0*Wins/Games).ToString("0.00")+"%";}}}
static class Ranking {
 public static long Now{get{return (long)(DateTime.UtcNow-new DateTime(1970,1,1)).TotalSeconds;}}
 public static string Family(string game){string s=(game??"").ToUpperInvariant();return s=="XZY"?"cn":new[]{"XZYSTEAM","XZYJP","XZYGAT","XZYTW"}.Contains(s)?"global":"";}
 public static int NameArea(string game){string s=(game??"").ToUpperInvariant();return s=="XZY"?101:s=="XZYJP"?103:new[]{"XZYSTEAM","XZYGAT","XZYTW"}.Contains(s)?102:0;}
 public static bool IsSelf(Snapshot s,int area,string id){if(s==null||string.IsNullOrEmpty(id))return false;string family=area==101?"cn":area==102||area==103?"global":"";return family!=""&&(s.IsAggregate?s.ViewSources:new List<Snapshot>{s}).Any(x=>!x.Demo&&Family(x.GameCode)==family&&x.Uid==id);}
 public static RankSeason Current(IEnumerable<RankSeason> ss,long now){return ss.OrderByDescending(s=>s.StartTime).FirstOrDefault(s=>s.StartTime<=now&&s.EndTime>=now);}
 public static List<RankSeason> Seasons(object raw){var seen=new HashSet<int>();return J.List(raw).Select(s=>{var r=new RankSeason{Code=(int)J.Num(J.Get(s,"Code")),Name=J.Str(s,"Name"),StartTime=J.Num(J.Get(s,"StartTime")),EndTime=J.Num(J.Get(s,"EndTime"))};if(r.Code<1||r.Code>1000||r.StartTime<1||r.EndTime<=r.StartTime||!seen.Add(r.Code))throw new Exception("官网赛季字段无效");return r;}).OrderByDescending(s=>s.StartTime).ToList();}
 public static RankBoard Board(object raw,int area,int mode,RankSeason season){if(!new[]{101,102,103}.Contains(area)||!new[]{12,22}.Contains(mode)||season==null)throw new Exception("榜单参数无效");var rows=J.List(J.Get(raw,"List"));if(rows.Count>1000)throw new Exception("榜单场数过多");var seen=new HashSet<string>();var b=new RankBoard{AreaId=area,Mode=mode,SeasonCode=season.Code,SeasonName=season.Name,FetchedAt=Now};foreach(var p in rows){string id=J.Str(p,"Id");var r=new RankPlayer{Id=id,Name=J.Str(p,"Name"),Dan=J.Str(p,"DanName"),Order=(int)J.Num(J.Get(p,"Order")),Score=J.Num(J.Get(p,"LadderScore"))};if(id.Length==0||id.Length>80||id.Any(c=>c<'0'||c>'9')||!seen.Add(id)||r.Order<1||r.Score<0||r.Name.Length>200)throw new Exception("官网榜单玩家字段无效");b.Players.Add(r);}b.Players=b.Players.OrderBy(p=>p.Order).ToList();return b;}
 public static List<RankEncounter> Annotate(RankBoard board,Snapshot s,int mode){var uid=new Dictionary<string,Dictionary<string,string>>();var names=new Dictionary<string,Dictionary<string,string>>();if(s!=null)foreach(var b in s.Battles.Where(b=>mode==0||b.Mode==mode)){string game=string.IsNullOrEmpty(b.ViewGameCode)?s.GameCode:b.ViewGameCode,f=Family(game);int area=NameArea(game);if(f=="")continue;foreach(var p in b.EnemyTeamPlayers){bool has=!string.IsNullOrEmpty(p.Uid);var map=has?uid:names;string key=has?f+"|"+p.Uid:area+"|"+p.Name;if(!has&&(area==0||string.IsNullOrEmpty(p.Name)))continue;Dictionary<string,string> hits;if(!map.TryGetValue(key,out hits))map[key]=hits=new Dictionary<string,string>();hits[b.Id]=b.Result;}}var duplicates=board.Players.GroupBy(p=>p.Name).ToDictionary(g=>g.Key,g=>g.Count());return board.Players.Select(p=>{var r=new RankEncounter{Player=p};var hits=new Dictionary<string,string>();Dictionary<string,string> exact;if(uid.TryGetValue((board.AreaId==101?"cn":"global")+"|"+p.Id,out exact))foreach(var h in exact)hits[h.Key]=h.Value;Dictionary<string,string> fallback;if(duplicates[p.Name]==1&&names.TryGetValue(board.AreaId+"|"+p.Name,out fallback))foreach(var h in fallback)if(!hits.ContainsKey(h.Key)){hits[h.Key]=h.Value;r.Named++;}r.Games=hits.Count;r.Wins=hits.Values.Count(v=>v=="win");return r;}).ToList();}
 public static object Fetch(string endpoint,int area,int type,int season){if(!new[]{"season_list","ranking_list_new"}.Contains(endpoint))throw new Exception("接口无效");string url="https://xzy.shengtiangames.com/mini-game/xzy/battle-record/"+endpoint;if(endpoint=="ranking_list_new"){if(!new[]{101,102,103}.Contains(area)||!new[]{1,2}.Contains(type)||season<1||season>1000)throw new Exception("榜单参数无效");url+="?area_id="+area+"&banking_type="+type+"&season_code="+season;}ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(url);request.Method="GET";request.AllowAutoRedirect=false;request.Timeout=request.ReadWriteTimeout=25000;request.Headers["lang"]="zh-cn";request.Headers["game-code"]=area==102?"XZYSteam":area==103?"XZYJP":"XZY";using(var response=(HttpWebResponse)request.GetResponse()){if(response.StatusCode!=HttpStatusCode.OK)throw new Exception("HTTP "+(int)response.StatusCode);using(var input=response.GetResponseStream())using(var output=new MemoryStream()){byte[] buf=new byte[8192];int n;while((n=input.Read(buf,0,buf.Length))>0){if(output.Length+n>8*1024*1024)throw new Exception("榜单数据过大");output.Write(buf,0,n);}var raw=J.Json.DeserializeObject(Encoding.UTF8.GetString(output.ToArray()));if(J.Num(J.Get(raw,"code"))!=0)throw new Exception(J.Str(raw,"msg"));return J.Get(raw,"data");}}}
}
sealed partial class NativeForm {
 readonly ComboBox rankRegion=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=120},rankMode=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=130},rankSeason=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=155};readonly TextBox rankSearch=new TextBox{Width=190};readonly DataGridView rankGrid=Grid();readonly Label rankInfo=new Label{Dock=DockStyle.Top,Height=48,Padding=new Padding(8)};RankCache rankCache=new RankCache();bool rankFilling;int rankSequence;readonly HashSet<string> rankInFlight=new HashSet<string>();Func<string,int,int,int,object> rankFetch=Ranking.Fetch;
 string RankPath{get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"leaderboards.json");}}
 TabPage LeaderboardPage(){var page=new TabPage("排行榜");rankRegion.Items.AddRange(new object[]{new Choice{Id="101",Name="国服"},new Choice{Id="102",Name="亚服"},new Choice{Id="103",Name="日本服"}});rankMode.Items.AddRange(new object[]{new Choice{Id="22",Name="2v2 天梯"},new Choice{Id="12",Name="1v1 天梯"}});rankRegion.SelectedIndex=rankMode.SelectedIndex=0;try{if(!preview&&File.Exists(RankPath)){var c=J.Json.Deserialize<RankCache>(File.ReadAllText(RankPath));if(c.Format!="XZY-LadderCache-PC"||c.Version!=1||c.Boards.Count>36||c.Seasons.Count>200)throw new Exception();foreach(var b in c.Boards){Ranking.Board(J.Json.DeserializeObject(J.Json.Serialize(new{List=b.Players.Select(p=>new{Id=p.Id,Name=p.Name,DanName=p.Dan,Order=p.Order,LadderScore=p.Score}).ToArray()})),b.AreaId,b.Mode,new RankSeason{Code=b.SeasonCode,Name=b.SeasonName});}rankCache=c;}}catch{rankCache=new RankCache();}FillRankSeasons();var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=50,Padding=new Padding(6)};bar.Controls.AddRange(new Control[]{FilterLabel("区服"),rankRegion,FilterLabel("天梯榜"),rankMode,FilterLabel("赛季"),rankSeason,FilterLabel("搜索昵称"),rankSearch,Action("刷新排行榜",()=>RefreshRank(true))});page.Controls.Add(rankGrid);page.Controls.Add(Fold("排行榜与交手统计说明",new Label{Text="官网每张榜目前返回前 100 名。榜单赛季可独立选择；交手场数及胜率来自右侧所选账号、赛季、模式的已导入记录，是你对该玩家的胜率。无交手显示 0 场 / —；网络失败保留缓存。",Padding=new Padding(8)},70,DockStyle.Bottom));page.Controls.Add(rankInfo);page.Controls.Add(bar);rankRegion.SelectedIndexChanged+=delegate{if(!rankFilling){RenderRank();RefreshRank(false);}};rankSeason.SelectedIndexChanged+=delegate{if(!rankFilling){RenderRank();RefreshRank(false);}};rankMode.SelectedIndexChanged+=delegate{if(!rankFilling){mode=int.Parse(Chosen(rankMode));Render();RefreshRank(false);}};rankSearch.TextChanged+=delegate{RenderRank();};return page;}
 void FillRankSeasons(){string selected=Chosen(rankSeason);rankFilling=true;rankSeason.Items.Clear();rankSeason.Items.Add(new Choice{Id="@current",Name="当前赛季"});foreach(var s in rankCache.Seasons.Where(s=>s.StartTime<=Ranking.Now))rankSeason.Items.Add(new Choice{Id=s.Code.ToString(),Name=s.Name});rankSeason.SelectedIndex=0;for(int i=0;i<rankSeason.Items.Count;i++)if(((Choice)rankSeason.Items[i]).Id==selected)rankSeason.SelectedIndex=i;rankFilling=false;}
 RankSeason ChosenRankSeason(){return Chosen(rankSeason)=="@current"?Ranking.Current(rankCache.Seasons,Ranking.Now):rankCache.Seasons.FirstOrDefault(s=>s.Code.ToString()==Chosen(rankSeason));}
 RankBoard ChosenBoard(){var s=ChosenRankSeason();return s==null?null:rankCache.Boards.FirstOrDefault(b=>b.AreaId.ToString()==Chosen(rankRegion)&&b.Mode.ToString()==Chosen(rankMode)&&b.SeasonCode==s.Code);}
 void RenderRank(){if(rankRegion.Items.Count==0)return;var board=ChosenBoard();rankInfo.Text="交手统计："+(data==null?"尚未导入战绩":data.SeasonName+" · "+Stats.Label(mode))+"\n"+(board==null?"尚未读取此榜单，请点击刷新。":rankRegion.Text+" · "+board.SeasonName+" · "+Stats.Label(board.Mode)+" · 前 "+board.Players.Count+" 名 · 更新 "+Beijing(board.FetchedAt));var t=new DataTable();t.Columns.Add("排名",typeof(int));t.Columns.Add("玩家昵称");t.Columns.Add("交手场数 / 你的胜率");t.Columns.Add("天梯分",typeof(long));if(board!=null)foreach(var r in Ranking.Annotate(board,data,mode).Where(r=>r.Player.Name.IndexOf(rankSearch.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)>=0))t.Rows.Add(r.Player.Order,r.Player.Name,(Ranking.IsSelf(data,board.AreaId,r.Player.Id)?"UID "+r.Player.Id+" · ":"")+"交手 "+r.Games+" 场 / "+r.Rate,r.Player.Score);rankGrid.DataSource=t;}
 void SaveRank(){rankCache.Boards=rankCache.Boards.OrderByDescending(b=>b.FetchedAt).Take(36).ToList();if(!preview){string temp=RankPath+".tmp";File.WriteAllText(temp,J.Json.Serialize(rankCache),new UTF8Encoding(false));if(File.Exists(RankPath))File.Replace(temp,RankPath,null);else File.Move(temp,RankPath);}}
 async void RefreshRank(bool force){ShowOperationStatus(status);if(preview&&rankFetch==(Func<string,int,int,int,object>)Ranking.Fetch)return;int seq=++rankSequence;try{status.Text="正在读取官网排行榜…";if(force||rankCache.Seasons.Count==0){rankCache.Seasons=Ranking.Seasons(await Task.Run(()=>rankFetch("season_list",101,0,0)));if(IsDisposed)return;FillRankSeasons();SaveRank();}var s=ChosenRankSeason();if(s==null)throw new Exception("当前日期没有对应官网赛季，请选择历史赛季");int area=int.Parse(Chosen(rankRegion)),m=int.Parse(Chosen(rankMode));string key=area+":"+m+":"+s.Code;var old=ChosenBoard();if(!force&&old!=null&&Ranking.Now-old.FetchedAt<300){RenderRank();status.Text="显示最近榜单缓存；点击刷新可重新读取。";return;}if(!rankInFlight.Add(key))return;try{var raw=await Task.Run(()=>rankFetch("ranking_list_new",area,m==12?1:2,s.Code));if(IsDisposed)return;var b=Ranking.Board(raw,area,m,s);rankCache.Boards.RemoveAll(x=>x.Key==key);rankCache.Boards.Add(b);SaveRank();RenderRank();if(seq==rankSequence)status.Text="官网排行榜已刷新。";}finally{rankInFlight.Remove(key);}}catch(Exception e){if(!IsDisposed){RenderRank();if(seq==rankSequence)status.Text="排行榜读取失败："+e.Message+(ChosenBoard()!=null?"；继续显示缓存。":"");}}}
 void SyncRankMode(){if(rankMode.Items.Count==0)return;rankFilling=true;if(mode!=0)rankMode.SelectedIndex=mode<20?1:0;rankFilling=false;RenderRank();}
}
}
